                while (i < src.length) { const ch = src[i]; if (/\s/.test(ch)) { if (!inWs) { normSrc += " "; map.push(i); inWs = true; } i++; } else { normSrc += ch; map.push(i); inWs = false; i++; } }
                const fo = normSrc.split(an).length - 1;
