            const method = cdv.getUint16(p + 10, true), csize = cdv.getUint32(p + 20, true), usize = cdv.getUint32(p + 24, true);
            const nlen = cdv.getUint16(p + 28, true), elen = cdv.getUint16(p + 30, true), clen = cdv.getUint16(p + 32, true);
