      // Verdict â€” core = kv, d1, host, brain
      const core = [sh.checks.kv.ok, sh.checks.d1.ok, sh.checks.aura_host.ok, sh.checks.brain.ok];
      sh.verdict = core.every(Boolean) ? "HEALTHY" : "DEGRADED";
